      "ar": "قَيِّمًا لِّيُنذِرَ بَأْسًا شَدِيدًا مِّن لَّدُنْهُ وَيُبَشِّرَ الْمُؤْمِنِينَ الَّذِينَ يَعْمَلُونَ الصَّـٰلِحَٰتِ أَنَّ لَهُمْ أَجْرًا حَسَنًا",
