        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Birkaç genç mağaraya sığınmış: \"Rabbimiz! Katından bize rahmet ver ve işimizde doğruyu göster, bizi başarılı kıl\" demişlerdi"
        }
