        "tr": {
          "auteur": "Diyanet İşleri Başkanlığı",
          "texte": "Her iki bahçe de ürünlerini vermişlerdi, hiçbir şeyi de eksik bırakmamışlardı. İkisinin arasından bir de ırmak akıtmıştık"
        }
